  let userinfo
  let rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) {
    userinfo = a.slice(0, at)
    rest = a.slice(at + 1)
  }
  const rb = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', rb + 1)
  let host = rest
  let port
  if (colon >= 0) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

