    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

export function badPercent(s) {
  return /%(?![0-9A-Fa-f]{2})/.test(s)
}

function normPct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export class UriError extends Error {}

// Returns the first component name carrying a truncated percent-encoding.
function checkPercent(r) {
  const parts = r.authority === undefined ? {} : splitAuthority(r.authority)
  const checks = [
    ['path', r.path],
    ['userinfo', parts.userinfo],
    ['host', parts.host],
    ['query', r.query],
    ['fragment', r.fragment],
  ]
  for (const [name, v] of checks) if (v !== undefined && badPercent(v)) return name
  return null
}

export function normalize(r) {
  const bad = checkPercent(r)
  if (bad) throw new UriError(`the ${bad} has a truncated percent-encoding`)
  const scheme = r.scheme === undefined ? undefined : lowerAscii(r.scheme)
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  let hasAuth = r.authority !== undefined
  if (hasAuth) {
    const p = splitAuthority(r.authority)
    let a = ''
    if (p.userinfo !== undefined) a += normPct(p.userinfo) + '@'
    a += lowerAscii(normPct(p.host))
    if (p.port !== undefined && p.port !== '' && p.port !== DEFAULT_PORTS[scheme]) a += ':' + normPct(p.port)
    out += '//' + a
  }
  let path = removeDots(normPct(r.path))
  if (hasAuth && path === '') path = '/'
  out += path
  if (r.query !== undefined) out += '?' + normPct(r.query)
  if (r.fragment !== undefined) out += '#' + normPct(r.fragment)
  return out
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else if (ref.path === '') {
    Object.assign(t, {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== undefined ? ref.query : base.query,
      fragment: ref.fragment,
    })
  } else {
    let path
    if (ref.path.startsWith('/')) path = ref.path
    else if (base.authority !== undefined && base.path === '') path = '/' + ref.path
    else {
      const i = base.path.lastIndexOf('/')
      path = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
    }
    Object.assign(t, {
      scheme: base.scheme,
      authority: base.authority,
      path: removeDots(path),
      query: ref.query,
      fragment: ref.fragment,
    })
  }
  return t
}
